#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_prepend_enough_space_no_resize(void) {
    // Setup: create a buffer with enough space to prepend without resizing
    // Let's say buffer contains "World", and we want to prepend "Hello "
    // The buffer's allocated size must be > strlen("Hello ") + strlen("World") = 6 + 5 = 11
    // We'll use a helper to create the buffer with "World"
    buffer_t *buf = helper_create_buffer_with_content("World");
    TEST_ASSERT_NOT_NULL(buf);

    // Artificially increase the buffer's allocated size to ensure no resize is needed
    // Let's assume buffer_t has a 'len' field for allocated size
    // We'll set it to 32 for this test (should be safe for the prepend)
    buf->len = 32;

    // Test: prepend "Hello " to the buffer
    int ret = buffer_prepend(buf, "Hello ");
    TEST_ASSERT_EQUAL_INT(0, ret);

    // Assert: buffer content is now "Hello World"
    helper_assert_buffer_content(buf, "Hello World");
    // Assert: buffer string length is 11
    helper_assert_buffer_length(buf, 11);
    // Assert: buffer size is still 32 (no resize)
    helper_assert_buffer_size(buf, 32);

    // Cleanup
    helper_free_buffer(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_prepend_enough_space_no_resize);
    return UNITY_END();
}

